// Line icons (Lucide-style geometry, ISC licence) drawn as inline SVG: one consistent, sober set.
const ICONS={trend:'<polyline points="22 7 13.5 15.5 8.5 10.5 2 17"/><polyline points="16 7 22 7 22 13"/>',plus:'<path d="M12 5v14M5 12h14"/>',
create:'<circle cx="12" cy="12" r="10"/><path d="M8 12h8M12 8v8"/>',studio:'<rect x="2" y="6" width="20" height="14" rx="2"/><path d="M2 10h20M6 6l2 4M11 6l2 4M16 6l2 4"/>',
users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
library:'<path d="m16 6 4 14M12 6v14M8 8v12M4 4v16"/>',book:'<path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2zM22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/>',
theme:'<circle cx="12" cy="12" r="10"/><path d="M12 18a6 6 0 0 0 0-12z" fill="currentColor"/>',refresh:'<path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8M21 3v5h-5M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16M8 16H3v5"/>',
download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><path d="M12 15V3"/>',external:'<path d="M15 3h6v6M10 14 21 3M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>',
image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.1-3.1a2 2 0 0 0-2.8 0L6 21"/>',film:'<rect x="2" y="2" width="20" height="20" rx="2"/><path d="M7 2v20M17 2v20M2 12h20M2 7h5M2 17h5M17 17h5M17 7h5"/>',
clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',coins:'<circle cx="8" cy="8" r="6"/><path d="M18.09 10.37A6 6 0 1 1 10.34 18M7 6h1v4M16.71 13.88l.7.71-2.82 2.82"/>',
check:'<path d="M20 6 9 17l-5-5"/>',eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',heart:'<path d="M19 14c1.49-1.46 3-3.21 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.76 0-3 .5-4.5 2-1.5-1.5-2.74-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4.05 3 5.5l7 7Z"/>'};
const ico=(n,cls='')=>`<svg class="ico ${cls}" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||''}</svg>`;
const paintIcons=(root=document)=>root.querySelectorAll('i[data-icon]').forEach(i=>{if(!i.firstChild)i.innerHTML=ico(i.dataset.icon);});
let state=null,page='studio',selected=new URLSearchParams(location.hash.slice(1)).get('job'),lastSnapshot='',uploadSlot=null;
// Deep link: /#job=<id> opens that production (bookmarks, support, interface tests).
// Same presence window as the server (75 s): the extension polls every 30 s.
const ONLINE_MS=75000;
// Unsaved story corrections must survive the periodic refresh.
let reviewDirty=false;
// Connector heartbeats change only `seen`; they must not redraw the page (open panels, playing videos).
const renderSnapshot=s=>JSON.stringify({...s,clients:Object.fromEntries(Object.entries(s.clients||{}).map(([id,c])=>[id,{...c,seen:undefined}]))});
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={research:'Recherche',script:'Scénario',characters:'Personnages',images:'Scènes',clips:'Clips Flow',quality:'Contrôle qualité',cover:'Couverture',edit:'Montage',done:'Final'};
const statusLabels={running:'En production',paused:'En pause',attention:'À vérifier',waiting_research:'Références requises',waiting_credit:'Crédits insuffisants',waiting_review:'Histoire à relire',waiting_quota:'Limite atteinte, reprise automatique',waiting_account:'Changement de compte',waiting_night:'En file de nuit',rendering:'Montage en cours',done:'Prêt à télécharger'};
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const b=await r.json();if(!r.ok)throw Error(b.error||'Erreur');return b}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
async function refresh(force=false){try{const next=await api('/api/state'),snapshot=renderSnapshot(next);next.filonJobs=next.jobs.filter(j=>j.filon_only);next.jobs=next.jobs.filter(j=>!j.filon_only);state=next;const clients=Object.values(state.clients).filter(c=>Date.now()-Date.parse(c.seen)<ONLINE_MS);$('#bridgeBadge').textContent=clients.length?`${clients.length} connecteur(s) en ligne`:'Connecteur à configurer';$('#bridgeBadge').classList.toggle('online',!!clients.length);if(force||snapshot!==lastSnapshot){lastSnapshot=snapshot;if(!reviewDirty&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))render()}}catch(e){toast('Studio inaccessible : '+e.message)}}
const profileOptions=(current)=>`<option value="">Choisir un profil Flow</option>`+state.profiles.map(p=>`<option value="${p.id}" ${current===p.id?'selected':''}>${esc(p.label)} · ${p.balance} crédits déclarés</option>`).join('');
function intro(title,sub,button=true){return `<div class="intro"><div><h1>${title}</h1><p>${sub}</p></div>${button?`<button class="primary" data-action="new">${ico('plus')} Créer une vidéo</button>`:''}</div>`}
function list(){if(!state.jobs.length)return `<div class="empty"><div class="empty-symbol">${ico('film')}</div><h3>Votre prochaine histoire commence ici</h3><p>Donnez une direction à l’IA. Le studio commence par rechercher des références, puis prépare votre épisode original.</p><button class="secondary" data-action="new">${ico('create')} Créer mon premier épisode</button></div>`;return `<div class="project-list">${state.jobs.map(j=>`<button class="project ${selected===j.id?'selected':''}" data-job="${j.id}">${j.cover?`<img class="project-thumb" src="${j.cover}" alt="Couverture">`:`<span class="project-thumb">${ico('film')}</span>`}<span class="project-content"><b>${esc(j.title)}</b><small>${j.config.provider==='claude'?'Claude':'ChatGPT'} · ${j.config.scene_count*(j.config.clip_seconds||8)} s · ${esc(j.config.language||"Deutsch")} · ${({'gemini_omni_flash':'Omni Flash','veo_3_1_lite':'Veo Lite','veo_3_1_fast':'Veo Fast','veo_3_1_quality':'Veo Quality'}[j.config.flow_model]||'Flow')} · ${esc(labels[j.stage])}</small></span><span class="pill ${j.status}">${esc(statusLabels[j.status]||j.status)}</span></button>`).join('')}</div>`}
// P2-10: night queue, one production at a time, with its log.
function nightPanel(){const n=state.night||{ids:[],log:[],active:false};if(!n.ids.length&&!n.log.length)return '';const title=id=>esc(state.jobs.find(j=>j.id===id)?.title||id);return `<section class="panel night"><div class="section-title"><h2>File de nuit ${n.active?'· en cours':'· arrêtée'}</h2><div class="actions">${n.active?'<button class="secondary" data-night="stop">Arrêter la file</button>':n.ids.length?'<button class="primary" data-night="start">Démarrer la file de nuit</button>':''}</div></div><p class="hint">Une production à la fois. Échecs réessayables relancés jusqu’à 3 fois ; limites et crédits attendus ; une production qui a besoin de vous est retirée avec la raison. Le PC ne se met pas en veille pendant la file (Windows).</p><ol>${n.ids.map(id=>`<li>${title(id)} · ${esc(statusLabels[state.jobs.find(j=>j.id===id)?.status]||'')}${n.failures?.[id]?` · essais ${n.failures[id]}/3`:''}</li>`).join('')}</ol>${n.log.length?`<details><summary>Journal de la file</summary>${n.log.slice(-15).reverse().map(x=>`<p class="hint"><time>${esc(new Date(x.at).toLocaleTimeString('fr-FR'))}</time> ${esc(x.text)}</p>`).join('')}</details>`:''}</section>`}
// Atelier-like "Le Filon": every TikTok reference found by the research, best signal first.
function filon(){const seen=new Map();for(const j of [...state.jobs,...(state.filonJobs||[])])for(const c of j.candidates||[])if(!seen.has(c.url)||(c.score||0)>(seen.get(c.url).score||0))seen.set(c.url,c);
const rows=[...seen.values()].sort((a,b)=>(b.score||0)-(a.score||0)).slice(0,60);const fmt=n=>n==null?'—':n>=1e6?(n/1e6).toFixed(1).replace('.0','')+' M':n>=1e3?Math.round(n/1e3)+' k':String(Math.round(n));
const running=(state.filonJobs||[]).find(j=>!['done','attention','paused'].includes(j.status));const last=state.settings.filon_refreshed;
return `<div class="intro"><div><h1>Le Filon</h1><p>Ce qui marche dans ta niche. Glisse une vidéo sur la zone de création, colle un lien TikTok n’importe où, ou clique pour créer.</p></div><div class="actions"><label class="check switch"><input type="checkbox" id="filonAuto" ${state.settings.filon_auto?'checked':''}> Actualiser toutes les 2 h</label><button class="primary" data-filon-refresh="1" ${running?'disabled':''}>${ico('refresh',running?'spin':'')} ${running?'Actualisation…':'Actualiser'}</button></div></div>
<div class="dropzone" data-drop="create">${ico('create')}<div><b>Créer une vidéo</b><span>Dépose une vidéo du Filon ici, ou colle un lien TikTok (Ctrl+V)</span></div><button class="secondary" data-action="new">Partir d’une idée</button></div>
<p class="hint filon-meta">${rows.length} vidéo(s) relevée(s)${last?' · dernière actualisation '+new Date(last).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'}):''}${running?' · recherche TikTok en cours dans la fenêtre FruchtDrama':''}</p>
${rows.length?`<div class="filon-grid">${rows.map((c,k)=>`<article class="filon-card" draggable="true" data-url="${esc(c.url)}" style="--i:${k%12}"><div class="filon-media">${c.thumb?`<img src="${esc(c.thumb)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">`:''}<span class="filon-rank">${k+1}</span><div class="filon-stats">${c.metric_kind==='views'?ico('eye')+' '+fmt(c.views):c.metric_kind==='likes'?ico('heart')+' '+fmt(c.likes):''}${c.age_days?`<span>${esc(c.age_days)} j</span>`:''}</div><div class="filon-hover"><button class="primary" data-action="new" data-source="${esc(c.url)}">${ico('create')} Créer d’après</button><button class="secondary" data-copy="${esc(c.url)}">Copier le lien</button><a class="secondary" href="${esc(c.url)}" target="_blank" rel="noopener">${ico('external')} Ouvrir</a></div></div><p class="filon-title">${esc((c.title||c.url).replace(/\s+/g,' ').slice(0,110))}</p></article>`).join('')}</div>`:`<div class="filon-empty">${Array.from({length:8},(_,k)=>`<div class="skeleton" style="--i:${k}"></div>`).join('')}<p>Aucune vidéo relevée. Clique sur <b>Actualiser</b> : la recherche TikTok s’ouvre dans la fenêtre FruchtDrama (compte TikTok connecté conseillé).</p></div>`}`}
function studio(){const done=state.jobs.filter(j=>j.status==='done').length,active=state.jobs.filter(j=>j.status!=='done').length,balance=state.profiles.reduce((a,p)=>a+p.balance,0);return intro('Le studio de vos histoires.','De la première idée au dernier rebondissement.')+`${nightPanel()}<section class="hero"><div class="hero-copy"><span class="eyebrow">VOTRE UNIVERS, VOTRE SIGNATURE</span><h2>Petits fruits.<br>Grandes histoires.</h2><span class="badge">MULTILINGUE &nbsp;·&nbsp; ANIMATION 3D &nbsp;·&nbsp; 9:16</span></div><div class="hero-art"><img src="/mascot.png" alt="Mascotte fraise expressive en animation 3D"><div class="floating"><b>Une histoire originale</b>Un nouveau twist à chaque épisode</div><div class="floating bottom">Votre univers reste cohérent</div></div><span class="hero-index">FRUCHTDRAMA / STUDIO 01</span></section><div class="stats"><div class="stat"><span class="stat-icon">${ico('library')}</span><div><small>Épisodes terminés</small><strong>${done}<span>dans votre bibliothèque</span></strong></div></div><div class="stat"><span class="stat-icon">${ico('clock')}</span><div><small>Productions ouvertes</small><strong>${active}<span>à suivre dans le studio</span></strong></div></div><div class="stat"><span class="stat-icon">${ico('coins')}</span><div><small>Crédits déclarés · ${state.profiles.length} profil(s)</small><strong>${balance}<span>solde réel à vérifier dans Flow</span></strong></div></div></div><div class="columns"><section class="panel"><div class="section-title"><h3>Vos productions</h3><span class="muted">${state.jobs.length} épisode(s)</span></div>${list()}</section><section class="panel"><h3>Une chaîne, neuf étapes.</h3><div class="process"><div class="process-row"><span>01</span><div><b>Repérer une histoire qui résonne</b><small>Recherche et comparaison des références</small></div></div><div class="process-row"><span>02</span><div><b>Créer votre version originale</b><small>Scénario, personnages et scènes</small></div></div><div class="process-row"><span>03</span><div><b>Donner vie à l’histoire</b><small>Clips parlés, montage et couverture</small></div></div></div><div class="notice">Connecteurs navigateur expérimentaux. Les comptes IA et Flow restent indépendants.</div><button class="secondary wide" style="margin-top:15px" data-page="connections">Configurer mes comptes</button></section></div>${selected?detail():''}`}
function editorialReview(j){const c=j.script?.creative_selection;if(!Array.isArray(c?.candidates))return '';return `<details><summary>Choix éditorial · 5 concepts comparés</summary><p class="hint">Notes proposées par l’IA pour comparer les idées ; elles ne prédisent pas les vues.</p>${c.candidates.map((x,i)=>`<div class="profile-card"><b>${i===c.selected_index?ico('check')+' Retenu · ':''}${esc(x.title)}</b><p>${esc(x.hook)}</p><small>${esc(x.conflict)} · ${esc(x.setting)}</small></div>`).join('')}<p class="hint">${esc(c.reason||'')}</p></details>`}
function qualityReview(j){const q=j.quality_report;if(!q)return '';const issues=[...(q.hard_errors||[]),...(q.warnings||[])];return `<details open><summary>Contrôle qualité des clips</summary><p class="hint">${esc(({pass:'Contrôles locaux réussis',review_required:'Vérification nécessaire',checked:'Contrôles disponibles terminés',approved_with_reservations:'Validé avec réserves'})[q.status]||q.status)} · Les images échantillonnées ne certifient pas les lèvres ni l’identité des voix.</p>${issues.map(x=>`<p>${esc(x)}</p>`).join('')}${(q.clips||[]).map((c,i)=>`<p><b>Scène ${i+1}</b> · ${esc(c.speech?.text||'Transcription indisponible')} ${c.speech?`· correspondance avec le scénario : ${Math.round(c.speech.match*100)} %`:''}</p>`).join('')}${q.visual?`<p><b>Cohérence entre scènes :</b> ${esc(q.visual.continuity.detail)}</p>${q.visual.scenes.map(x=>`<p>Scène ${x.index+1} · ${esc(({pass:'Conforme sur les images observées',issue:'Problème détecté',uncertain:'Incertain'})[x.status]||x.status)} : ${esc(x.detail)}</p>`).join('')}`:''}<a class="secondary" href="/media/${j.id}/${q.visual?'quality-report':'quality-local'}.json?download=1" download>${ico('download')} Rapport qualité</a>${j.stage==='quality'&&j.status==='attention'&&!q.hard_errors?.length?`<p class="hint">Vérifiez les clips ci-dessous avant de confirmer. Cette validation conserve les clips et ne lance aucune nouvelle génération Flow.</p><button class="secondary" data-command="${q.visual?'approve_quality':'approve_speech'}">${q.visual?'J’ai vérifié les réserves, continuer':'J’ai écouté les dialogues, continuer la revue visuelle'}</button>`:''}</details>`}
function detail(){const j=state.jobs.find(j=>j.id===selected);if(!j)return '';const task=state.tasks.find(t=>t.job===j.id&&['queued','claimed'].includes(t.status));const steps=Object.keys(labels),idx=steps.indexOf(j.stage);return `<section class="panel detail"><div class="detail-head"><div><span class="eyebrow">PRODUCTION ${j.id.slice(0,6).toUpperCase()}</span><h2 style="margin-top:8px">${esc(j.title)}</h2></div><div class="actions"><button class="secondary" data-command="pause">Pause</button><button class="secondary" data-command="resume">Reprendre</button>${j.status!=='done'?(state.night?.ids||[]).includes(j.id)?'<button class="secondary" data-night="remove">Retirer de la file de nuit</button>':'<button class="secondary" data-night="add">Ajouter à la file de nuit</button>':''}<button class="secondary" data-delete-job="1">Supprimer…</button></div></div><div class="timeline">${steps.map((s,i)=>`<div class="step ${i<idx?'past':i===idx?'current':''}">${String(i+1).padStart(2,'0')} ${labels[s]}</div>`).join('')}</div><div class="detail-note">${esc(statusLabels[j.status]||j.status)}${task?` · ${esc(task.slot)} ${task.status==='claimed'?'est en cours dans le navigateur':'attend un connecteur disponible'}`:''}</div>${dryRunNotice(j)}${humanNotice(j)}${accountNotice(j)}${uncertainClips(j)}${scriptReview(j)}<div class="form-grid">${(j.config.video_engine||'flow')!=='flow'?`<p class="hint engine-badge">Moteur vidéo : <b>${esc({grok:'Grok Imagine',arena:'LMArena vidéo'}[j.config.video_engine])}</b> · comptes dans Connexions</p>`:''}<label ${(j.config.video_engine||'flow')!=='flow'?'hidden':''}>Profil Flow de cette production<select id="jobProfile">${profileOptions(j.flow_profile)}</select><span class="hint">Choisir un profil, puis Reprendre. Les clips déjà reçus restent conservés.</span></label><label>IA de scénario<select id="jobProvider"><option value="chatgpt" ${j.config.provider==='chatgpt'?'selected':''}>ChatGPT</option><option value="claude" ${j.config.provider==='claude'?'selected':''}>Claude</option></select><span class="hint">Les images restent confiées à ChatGPT ; changer l’IA ne supprime aucun média.</span></label></div>${j.selected?`<p class="hint">Référence retenue : <a href="${esc(j.selected.url)}" target="_blank" rel="noreferrer">ouvrir TikTok ${ico('external')}</a> · ${esc(j.selected.basis)}. Ce choix ne garantit pas la viralité.</p>`:''}${editorialReview(j)}${qualityReview(j)}${j.candidates.length?`<details><summary>Références comparées (${j.candidates.length})</summary>${j.candidates.map(c=>`<div class="candidate"><div><a href="${esc(c.url)}" target="_blank" rel="noreferrer">${esc(c.title.slice(0,100)||c.url)}</a><small>${esc(c.basis)} · ${c.views??c.likes??c.signal??'inconnu'} · observé le ${new Date(c.observed_at).toLocaleDateString('fr')}</small></div><button class="secondary" data-source="${esc(c.url)}">Choisir</button></div>`).join('')}</details>`:''}<details><summary>Ajouter des références vérifiées</summary><p class="hint">Un lien TikTok par ligne, puis « | » et le nombre de vues, si connu. Ne saisissez pas des likes à la place des vues.</p><textarea id="researchInput" rows="3" placeholder="https://www.tiktok.com/@compte/video/123456789 | 120000"></textarea><button class="secondary" data-action="research">Enregistrer les références</button></details>${task?`<details><summary>Prompt de la tâche · copie manuelle possible</summary><pre>${esc(task.payload.prompt||task.payload.query)}</pre><button class="secondary" data-copy-task="${task.id}">Copier le prompt</button></details>`:''}<details><summary>Importer un scénario JSON</summary><p class="hint">Pour reprendre une réponse ChatGPT/Claude ou contourner une panne du connecteur. Le studio valide la structure et les locuteurs.</p><textarea id="scriptInput" rows="5" placeholder="Collez ici le JSON du scénario"></textarea><button class="secondary" data-action="script">Valider le scénario</button>${j.script?`<pre>${esc(JSON.stringify(j.script,null,2))}</pre>`:''}</details>${j.characters.length?`<h3 style="margin-top:25px">Personnages</h3><div class="assets">${usesSheet(j)?asset(j,j.character_sheet_file,'Feuille commune : '+j.characters.map(c=>c.name).join(', '),'characters'):j.characters.map(c=>asset(j,c.file,c.name,'character:'+c.id)).join('')}</div><h3>Scènes et clips</h3><div class="assets">${j.scenes.map((s,i)=>`<div class="asset">${s.image?`<img src="${assetURL(j,s.image)}" alt="Scène ${i+1}">`:`<div class="asset-placeholder">${ico('image')}</div>`}<b>Scène ${i+1} · ${esc(j.config.clip_seconds||8)} s</b><button class="secondary" data-upload="image:${i}" data-type="image">${s.image?'Remplacer':'Importer'} l’image</button>${s.image?`<button class="secondary redo" data-redo="image:${i}" data-has-clip="${s.clip?1:0}">Refaire l’image…</button>`:''}${s.clip?`<video src="${assetURL(j,s.clip)}" controls preload="metadata"></video>`:''}<button class="secondary" style="margin-top:7px" data-upload="clip:${i}" data-type="video">${s.clip?'Remplacer':'Importer'} le clip</button>${s.clip?`<button class="secondary redo" data-redo="clip:${i}">Refaire le clip…</button>`:''}</div>`).join('')}</div>`:''}${j.final?`<h3 style="margin-top:24px">Votre épisode est prêt</h3><video class="final-video" src="${j.final}" controls></video><div class="actions"><a class="primary" href="${j.final}" download="fruchtdrama.mp4">${ico('download')} Télécharger le MP4</a><a class="secondary" href="${j.cover}?download=1" download>${ico('download')} Couverture</a>${j.cover_file?'<button class="secondary" data-redo="cover">Refaire la couverture…</button>':''}<a class="secondary" href="/media/${j.id}/description.txt?download=1" download="description.txt">${ico('download')} Description</a><button class="secondary" data-action="copyDescription">Copier la description</button>${j.publication?`<a class="secondary" href="${j.publication}?download=1" download>${ico('download')} Kit de publication</a>`:''}<button class="secondary" data-series="1">Écrire la suite (partie ${(j.series?.part||1)+1})…</button></div><details><summary>Aperçu de la couverture et description</summary><img class="cover-preview" src="${j.cover}" alt="Couverture à télécharger"><label>Description TikTok<textarea id="finalDescription" readonly rows="5">${esc(j.script?.description||'')}</textarea></label></details><p class="hint">Sous-titres : alignement vocal lorsque le contrôle local le permet, sinon timing estimé. Vérifiez les répliques, les voix et les lèvres avant publication.</p>`:''}<div class="logs">${j.events.slice(-18).reverse().map(e=>`<p><time>${new Date(e.at).toLocaleTimeString('fr',{hour:'2-digit',minute:'2-digit'})}</time>${esc(e.text)}</p>`).join('')}</div></section>`}
const assetURL=(j,file)=>`/media/${j.id}/${file}`;
// One shared sheet for the cast (P1-2): shown once, replaceable as a whole.
const usesSheet=j=>j.character_sheet===1&&j.characters.length>1&&(!!j.character_sheet_file||!j.characters.some(c=>c.file));
function scriptReview(j){if(j.status!=='waiting_review'||!j.script)return '';const names=Object.fromEntries(j.characters.map(c=>[c.id,c.name]));return `<div class="review" id="scriptReview"><b>Relisez l’histoire avant de payer les images</b><p class="hint">Corrigez les répliques si besoin. Rien n’est généré avant votre validation.</p><div class="form-grid"><label>Titre<input data-field="title" value="${esc(j.script.title)}"></label><label>Titre de couverture<input data-field="cover_title" value="${esc(j.script.cover_title)}"></label></div><label>Description<textarea data-field="description" rows="3">${esc(j.script.description)}</textarea></label>${j.script.scenes.map((sc,i)=>`<div class="review-scene"><b>Scène ${i+1}</b><small>${esc(sc.meaning)}</small>${sc.dialogue.map(l=>`<label>${esc(names[l.speaker]||l.speaker)}<input data-scene="${i}" data-speaker="${esc(l.speaker)}" value="${esc(l.text)}"></label>`).join('')}</div>`).join('')}<div class="actions"><button class="secondary" data-action="saveScript">Enregistrer les corrections</button><button class="primary" data-action="approveScript">Valider l’histoire et lancer les images</button></div></div>`}
function reviewChanges(){const box=$('#scriptReview'),scenes=[];box.querySelectorAll('[data-scene]').forEach(input=>{const i=Number(input.dataset.scene);(scenes[i]=scenes[i]||{dialogue:[]}).dialogue.push({speaker:input.dataset.speaker,text:input.value})});const out={scenes};box.querySelectorAll('[data-field]').forEach(input=>out[input.dataset.field]=input.value);return out}
function dryRunNotice(j){if(!j.config.dry_run)return j.stage==='clips'||['research','script','characters','images'].includes(j.stage)?`<p class="hint"><button class="secondary" data-dry-run="1">Activer l’essai à blanc des clips</button> Prépare chaque clip dans Flow sans l’envoyer : aucun crédit consommé.</p>`:'';return `<div class="notice dry"><b>Essai à blanc des clips Flow</b><p class="hint">${j.dry_run_passed?'Essai réussi : Flow est prêt (modèle, coût, format, image et prompt vérifiés). Rien n’a été envoyé ni facturé.':'Les clips seront préparés dans Flow puis arrêtés juste avant l’envoi. Aucun crédit consommé.'}</p><button class="primary" data-dry-run="0">Passer en production réelle</button></div>`}
// P5-08: guided account change inside the FruchtDrama window, and automatic wait for a limit renewal.
function accountNotice(j){if(j.status==='waiting_account'&&j.account_switch)return `<div class="notice human"><b>Changez de compte ${esc(j.account_switch.label||'')}</b><p class="hint">Le compte ${esc(j.account_switch.from||'précédent')} a atteint sa limite. Dans la fenêtre FruchtDrama, ouvrez l’onglet du site, déconnectez-vous, connectez-vous vous-même à <b>${esc(j.account_switch.to)}</b>, puis cliquez ci-dessous. L’identité affichée est vérifiée avant tout envoi.</p><button class="primary" data-action="accountSwitched">J’ai changé de compte</button></div>`;if(j.status==='waiting_quota'&&j.wait_until)return `<div class="notice dry"><b>Limite atteinte</b><p class="hint">Reprise automatique vers ${esc(new Date(j.wait_until*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}))}. Vous pouvez aussi ajouter un compte dans Connexions.</p></div>`;return ''}
// P2-06: learned limits of ChatGPT / Claude, with a manual reset after an account change.
function quotaPanel(){const rows=state.quota_status||[];return `<section class="panel"><h2>Limites apprises</h2><p class="hint">Mesurées au moment où un service refuse (fenêtre de 6 h). Estimations, pas des chiffres officiels.</p>${rows.map(q=>`<div class="profile-card"><b>${esc(q.label)}</b><div class="code">${q.blocked?'à sa limite, reprise vers '+esc(new Date(q.retry_at*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})):q.capacity==null?esc(q.used)+' en 6 h · limite pas encore mesurée':'≈ '+esc(q.remaining)+' restant(s) sur ≈ '+esc(q.capacity)}</div>${q.blocked?`<button class="secondary" data-forget-quota="${esc(q.service)}">J’ai changé de compte : oublier la limite</button>`:''}</div>`).join('')}</section>`}
// P4-1: support and data hygiene.
function supportPanel(){return `<section class="panel"><h2>Assistance et entretien</h2><p class="hint">Le rapport de panne ne contient ni jeton, ni code d’appairage, ni adresse e-mail. La purge garde une copie de sauvegarde dans data/sauvegardes.</p><div class="actions"><button class="secondary" data-support="report">Copier un rapport de panne</button><button class="secondary" data-support="purge">Nettoyer l’historique (copie gardée)</button></div><pre id="reportBox" hidden></pre></section>`}
function engineAccounts(){const rows=state.engine_accounts||[];const now=Date.now()/1000;return `<section class="panel"><h2>Comptes Grok et Arena</h2><p class="hint">Adresse seulement, jamais de mot de passe. Quand un compte atteint sa limite, le studio vous demande de vous connecter au suivant dans la fenêtre FruchtDrama.</p>${rows.map(a=>`<div class="profile-card"><b>${esc(a.label)}</b> · ${esc({grok:'Grok',arena:'Arena'}[a.engine]||a.engine)}<div class="code">${esc(a.email)} · ${a.wall&&a.wall.until>now?'limite atteinte, libre vers '+esc(new Date(a.wall.until*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})):'disponible'}</div><div class="actions">${a.wall&&a.wall.until>now?`<button class="secondary" data-forget-wall="${a.id}">Oublier la limite</button>`:''}<button class="secondary" data-delete-engine-account="${a.id}">Retirer</button></div></div>`).join('')}<form id="engineAccountForm"><div class="form-grid"><label>Moteur<select name="engine"><option value="grok">Grok Imagine</option><option value="arena">LMArena vidéo</option></select></label><label>Adresse du compte<input name="email" type="email" required maxlength="80" placeholder="adresse@exemple.com"></label></div><button class="secondary wide">Ajouter ce compte</button></form></section>`}
// P2-02: a login or anti-robot check needs the owner; the studio never bypasses it.
function humanNotice(j){const kind=j.status==='attention'&&j.last_error?.kind;const text={login:'Connexion requise : ouvrez l’onglet du fournisseur, connectez-vous vous-même, puis cliquez sur Reprendre.',challenge:'Vérification anti-robot affichée : résolvez-la vous-même dans l’onglet, puis cliquez sur Reprendre. FruchtDrama ne la contourne jamais.'}[kind];return text?`<div class="notice human"><b>Action de votre part requise</b><p class="hint">${text}</p></div>`:''}
function uncertainClips(j){const list=j.uncertain_clips||[];if(!list.length)return '';return `<div class="notice uncertain"><b>Envoi Flow incertain</b><p class="hint">Le clip a peut-être déjà été généré et facturé. Ouvrez le projet Flow : la passerelle récupère automatiquement un clip existant, ou importez-le ci-dessous. Confirmez seulement si aucun clip n’existe dans Flow.</p>${list.map(i=>`<button class="secondary" data-confirm-no-clip="clip:${i}">Scène ${i+1} : aucun clip dans Flow, autoriser une nouvelle génération</button>`).join('')}</div>`}
function asset(j,file,title,slot){return `<div class="asset">${file?`<img src="${assetURL(j,file)}" alt="${esc(title)}">`:`<div class="asset-placeholder">${ico('image')}</div>`}<b>${esc(title)}</b><button class="secondary" data-upload="${slot}" data-type="image">${file?'Remplacer':'Importer'}</button>${file&&!j.scenes.some(s=>s.image)?`<button class="secondary redo" data-redo="${slot}">Refaire…</button>`:''}</div>`}
let accountsTab='flow';
function connections(){const now=Date.now()/1000,online=c=>Date.now()-Date.parse(c.seen)<ONLINE_MS,clients=Object.values(state.clients),flowTotal=state.profiles.reduce((a,p)=>a+(p.balance||0),0),eng=state.engine_accounts||[],quota=(state.quota_status||[]);
const status=(cls,text)=>`<span class="state ${cls}">${esc(text)}</span>`;
const flowRow=p=>`<tr><td><b>${esc(p.label)}</b><small>${p.flow_url?'Session mémorisée':'Session à mémoriser depuis la passerelle'}</small></td><td class="num">${esc(p.balance)}<small>${p.credit_source==='flow'?'lu dans Flow':'déclaré'}${p.checked?' · '+new Date(p.checked).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'}):''}</small></td><td>${p.blocked==='credits'?status('bad','Épuisé'):(p.balance||0)<5?status('warn','Solde bas'):p.flow_url&&p.auto_enabled?status('ok','Actif'):p.flow_url?status('idle','Hors rotation'):status('warn','À mémoriser')}${p.credit_error?`<small>${esc(p.credit_error)}</small>`:''}</td><td class="row-actions">${p.flow_url?`<button class="secondary" data-check-credits="${p.id}">${ico('refresh')} Vérifier</button>`:''}<details class="row-more"><summary>Réglages</summary><label>Crédits disponibles<input type="number" id="balance-${p.id}" value="${p.balance}" min="0" max="100000"></label>${p.flow_url?`<label class="check"><input id="auto-${p.id}" type="checkbox" ${p.auto_enabled?'checked':''}> Inclure dans le passage automatique</label><label>Profil Chrome (facultatif)<input id="chrome-${p.id}" value="${esc(p.chrome_profile||'')}" placeholder="Default, Profile 1…"></label>`:''}<div class="code">Identifiant : ${p.id}</div><div class="actions"><button class="secondary" data-balance="${p.id}">Enregistrer</button><button class="secondary danger" data-delete-profile="${p.id}">Retirer</button></div></details></td></tr>`;
const engineRows=engine=>{const rows=eng.filter(a=>a.engine===engine);return rows.length?rows.map(a=>{const walled=a.wall&&a.wall.until>now;return `<tr><td><b>${esc(a.email)}</b><small>${esc(a.label!==a.email?a.label:'')}</small></td><td class="num">—<small>pas de solde affiché</small></td><td>${walled?status('bad','Limite atteinte · libre vers '+new Date(a.wall.until*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})):status('ok','Disponible')}</td><td class="row-actions">${walled?`<button class="secondary" data-forget-wall="${a.id}">Oublier la limite</button>`:''}<button class="secondary danger" data-delete-engine-account="${a.id}">Retirer</button></td></tr>`}).join(''):`<tr><td colspan="4" class="empty-row">Aucun compte. Ajoutez-en un ci-dessous.</td></tr>`};
const table=(title,sub,rows,extra='')=>`<section class="panel account-block"><div class="block-head"><div><h2>${title}</h2><p class="hint">${sub}</p></div>${extra}</div><table class="accounts"><thead><tr><th>Compte</th><th>Crédits</th><th>État</th><th></th></tr></thead><tbody>${rows}</tbody></table></section>`;
const addForm=e=>`<div class="add-inline"><h3>Ajouter un compte ${{flow:"Google Flow",grok:"Grok",arena:"Arena"}[e]}</h3><p class="hint">Adresse seulement, jamais de mot de passe. Connectez-vous ensuite vous-même au site, dans la fenêtre FruchtDrama.</p><form id="engineAccountForm" class="add-account"><label>Plateforme<select name="engine"><option value="flow" ${e==="flow"?"selected":""}>Google Flow</option><option value="grok" ${e==="grok"?"selected":""}>Grok Imagine</option><option value="arena" ${e==="arena"?"selected":""}>LMArena vidéo</option></select></label><label>Adresse du compte<input name="email" type="email" required maxlength="80" placeholder="adresse@exemple.com"></label><label class="flow-balance" ${e!=="flow"?"hidden":""}>Crédits disponibles<input name="balance" type="number" value="50" min="0" max="100000"></label><button class="primary">Ajouter</button></form></div>`;
const panes={flow:table('Google Flow','Crédits par compte. Quand un compte est épuisé, le studio passe au suivant dans la fenêtre FruchtDrama.',state.profiles.map(flowRow).join('')||`<tr><td colspan="4" class="empty-row">Aucun compte Flow.</td></tr>`,`<label class="check switch"><input id="flowAuto" type="checkbox" ${state.settings.flow_auto?'checked':''}> Passage automatique au compte suivant</label>`)+addForm('flow'),grok:table('Grok Imagine','Pas de solde lisible : la limite de chaque compte est apprise au premier refus.',engineRows('grok'))+addForm('grok'),arena:table('LMArena vidéo','Même principe que Grok : changement de compte guidé dans la fenêtre FruchtDrama.',engineRows('arena'))+addForm('arena'),ia:`<section class="panel account-block"><h2>ChatGPT et Claude</h2><p class="hint">Limites mesurées au moment où le service refuse (fenêtre de 6 h). Estimations, pas des chiffres officiels.</p><table class="accounts"><thead><tr><th>Service</th><th>Utilisé (6 h)</th><th>État</th><th></th></tr></thead><tbody>${quota.map(q=>`<tr><td><b>${esc(q.label)}</b></td><td class="num">${esc(q.used)}<small>${q.capacity==null?'limite non mesurée':'≈ '+esc(q.remaining)+' restant(s) sur ≈ '+esc(q.capacity)}</small></td><td>${q.blocked?status('bad','Limite · reprise '+new Date(q.retry_at*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})):status('ok','Disponible')}</td><td class="row-actions">${q.blocked?`<button class="secondary" data-forget-quota="${esc(q.service)}">J’ai changé de compte</button>`:''}</td></tr>`).join('')}</tbody></table></section>`,bridge:`<section class="panel account-block"><h2>Passerelle du navigateur</h2><p class="hint">Cliquez sur l’icône FruchtDrama épinglée dans Chrome : la fenêtre dédiée s’ouvre. Dans son onglet Passerelle, saisissez ce code.</p><div class="pair-row"><div class="big-code">${esc(state.pair_code)}</div><button class="secondary" data-action="copyCode">Copier le code</button></div><table class="accounts"><thead><tr><th>Navigateur</th><th>Rôle</th><th>État</th><th>Dernier contact</th></tr></thead><tbody>${clients.map(c=>`<tr><td><b>${esc(c.label)}</b></td><td>${esc({all:'Recherche, IA et vidéo',creation:'Recherche et IA',flow:'Vidéo uniquement'}[c.role]||c.role)}<small>IA : ${esc(c.ai_provider||'both')}</small></td><td>${online(c)?status('ok','En ligne'):status('idle','Hors ligne')}</td><td>${new Date(c.seen).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})}</td></tr>`).join('')||`<tr><td colspan="4" class="empty-row">Aucune passerelle appairée.</td></tr>`}</tbody></table></section>`,support:`${supportPanel()}<section class="panel"><h3>Environnement</h3><p class="hint">ffmpeg : <b>${state.ffmpeg?'détecté':'non détecté — requis pour exporter'}</b> · version ${esc(state.version||'')} · données dans le dossier local « data ». Aucune publication automatique.</p></section>`};
const tabs=[['flow','Google Flow',state.profiles.length],['grok','Grok',eng.filter(a=>a.engine==='grok').length],['arena','Arena',eng.filter(a=>a.engine==='arena').length],['ia','ChatGPT / Claude',''],['bridge','Passerelle',clients.filter(online).length+'/'+clients.length],['support','Assistance','']];
return intro('Mes comptes.','Tous vos comptes par plateforme : crédits, limites, état et rotation automatique.',false)+
`<div class="account-summary"><div class="stat"><div><small>Crédits Flow déclarés</small><strong>${flowTotal}<span>${state.profiles.length} compte(s)</span></strong></div></div><div class="stat"><div><small>Comptes Grok / Arena</small><strong>${eng.filter(a=>!(a.wall&&a.wall.until>now)).length}<span>disponible(s) sur ${eng.length}</span></strong></div></div><div class="stat"><div><small>Passerelles en ligne</small><strong>${clients.filter(online).length}<span>sur ${clients.length}</span></strong></div></div></div>`+`<div class="tabs" role="tablist">${tabs.map(([k,l,n])=>`<button role="tab" class="tab ${accountsTab===k?'active':''}" data-account-tab="${k}">${l}${n!==''?`<span>${n}</span>`:''}</button>`).join('')}</div><div class="tab-pane">${panes[accountsTab]}</div>`}
function guide(){return intro('Votre premier épisode.','Un démarrage simple, puis une production suivie étape par étape.',false)+`<section class="panel"><h2>Installation en quatre étapes</h2><ol class="hint" style="line-height:2.5"><li>Ajoutez un profil Flow dans Connexions et vérifiez son solde.</li><li>Dans Chrome, chargez le dossier extension en mode développeur, puis cliquez sur son icône : la fenêtre FruchtDrama s’ouvre et tout s’y passe. Dans son onglet Passerelle, saisissez le code d’appairage local.</li><li>Connectez-vous vous-même à ChatGPT ou Claude, TikTok et Flow. Dans l’extension, sélectionnez le profil Flow correspondant.</li><li>Créez un épisode. Laissez le studio et le navigateur actifs. Le premier essai sert à valider vos connecteurs.</li></ol><h3 style="margin-top:25px">Si un connecteur bloque</h3><p class="hint">Le studio passe en « À vérifier ». Le journal précise l’étape. Vous pouvez copier le prompt, générer le média vous-même puis l’importer au bon emplacement. Ne relancez pas un clip avant d’avoir vérifié s’il existe déjà dans Flow : une seconde génération peut coûter des crédits.</p><h3 style="margin-top:25px">Recherche et originalité</h3><p class="hint">La recherche est obligatoire. Le studio conserve les liens et la base du classement ; il n’invente pas les données manquantes et ne prétend pas connaître la répartition géographique des spectateurs. Le scénario doit être original, les références servent à identifier les thèmes et mécanismes narratifs.</p><h3 style="margin-top:25px">Votre budget gratuit</h3><p class="hint">Exemple Omni 720p : quatre clips de huit secondes à douze crédits coûtent quarante-huit crédits. Deux crédits restent si votre solde réel est cinquante, ce qui ne suffit pas à une nouvelle génération. Le studio réserve le coût au démarrage ; après un échec, vérifiez le solde réel. Le renouvellement des crédits reste à vérifier. Le passage au compte suivant fonctionne seulement pour les sessions Flow mémorisées et autorisées.</p><h3 style="margin-top:25px">Contrôle avant publication</h3><p class="hint">Le montage est automatique. Les sous-titres karaoké suivent la transcription quand elle est fiable, sinon un timing estimé. La production continue seule seulement si les paroles correspondent à 85 % au moins, sans défaut technique ni réserve visuelle. Regardez le MP4, vérifiez les voix et les lèvres.</p></section>
<section class="panel guide-new"><h2>Nouveautés de la version ${esc(state.version||'')}</h2><div class="guide-grid">
<div><h3>Fenêtre FruchtDrama</h3><p class="hint">Un clic sur l’icône de l’extension ouvre une fenêtre dédiée : studio, ChatGPT, Claude, TikTok, Flow, Grok et Arena s’y ouvrent, comptes compris.</p></div>
<div><h3>Trois moteurs vidéo</h3><p class="hint">Google Flow (8 s, crédits), Grok Imagine (6 s) et LMArena (4 à 10 s, expérimentaux). Commencez Grok et Arena par un essai à blanc.</p></div>
<div><h3>Changement de compte</h3><p class="hint">Flow passe seul au compte suivant. Pour Grok et Arena, le studio vous indique le compte à connecter puis vérifie l’identité avant d’envoyer.</p></div>
<div><h3>Limites et refus</h3><p class="hint">Une limite atteinte met la production en attente puis la relance seule. Une image refusée par ChatGPT est reformulée deux fois, même style.</p></div>
<div><h3>File de nuit</h3><p class="hint">Ajoutez des productions puis démarrez la file : une à la fois, erreurs techniques relancées, PC maintenu éveillé (Windows).</p></div>
<div><h3>Corriger sans tout refaire</h3><p class="hint">Relecture de l’histoire avant les images, « Refaire » d’un média avec une consigne, essai à blanc, une seule feuille de personnages.</p></div>
<div><h3>Séries et publication</h3><p class="hint">« Écrire la suite » réutilise les personnages déjà payés. Le kit de publication donne titre, description, hashtags et créneaux.</p></div>
<div><h3>Assistance</h3><p class="hint">Mes comptes, rubrique Assistance : rapport de panne sans secret, nettoyage avec copie de sauvegarde, suppression vers la corbeille.</p></div>
</div><p class="hint">Mode d’emploi complet : docs/MODE-EMPLOI.md.</p></section>`}
function render(){if(!state)return;document.querySelectorAll('nav button,header [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumb').innerHTML=`Espace de travail / <b>${({filon:'Le Filon',studio:'Studio',library:'Bibliothèque',connections:'Mes comptes',guide:'Mode d’emploi'})[page]}</b>`;paintIcons();$('#content').innerHTML=page==='filon'?filon():page==='studio'?studio():page==='connections'?connections():page==='guide'?guide():intro('Votre bibliothèque.','Les épisodes et leurs fichiers, réunis au même endroit.')+`<section class="panel">${list()}</section>`+(selected?detail():'');}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-page]');if(!el)return;try{if(el.dataset.page){if(reviewDirty&&!window.confirm('Des corrections de l’histoire ne sont pas enregistrées. Les abandonner ?'))return;reviewDirty=false;page=el.dataset.page;render();return}if(el.dataset.job){if(reviewDirty&&!window.confirm('Des corrections de l’histoire ne sont pas enregistrées. Les abandonner ?'))return;reviewDirty=false;selected=el.dataset.job;render();setTimeout(()=>$('.detail')?.scrollIntoView({behavior:'smooth',block:'start'}),50);return}const action=el.dataset.action;if(action==='new'){$('#createProfile').innerHTML=profileOptions(state.profiles[0]?.id);$('#createForm [name=source_url]').value=el.dataset.source||'';$('#createDialog').showModal()}if(action==='copyDescription'){const text=state.jobs.find(j=>j.id===selected)?.script?.description;if(!text)throw Error('Description indisponible');try{await navigator.clipboard.writeText(text);toast('Description copiée')}catch{const box=$('#finalDescription');box.closest('details').open=true;box.focus();box.select();toast('Texte sélectionné : appuyez sur Ctrl+C pour le copier')}return}if(action==='copyCode'){await navigator.clipboard.writeText(state.pair_code);toast('Code copié')}if(el.dataset.command){await api('/api/job/'+selected,{action:el.dataset.command,flow_profile:$('#jobProfile')?.value});await refresh(true)}if(el.dataset.source){await api('/api/job/'+selected,{action:'select',url:el.dataset.source});await refresh(true)}if(action==='research'){const rows=$('#researchInput').value.split('\n').filter(Boolean).map(l=>{const [url,n]=l.split('|');return {url:url.trim(),views:n?.trim()?Number(n.trim().replace(/\s/g,'')):null,title:'Référence ajoutée par le propriétaire'}});await api('/api/job/'+selected,{action:'research',candidates:rows});await refresh(true)}if(action==='script'){await api('/api/job/'+selected,{action:'script',script:JSON.parse($('#scriptInput').value)});await refresh(true)}if(el.dataset.copyTask){const t=state.tasks.find(t=>t.id===el.dataset.copyTask);await navigator.clipboard.writeText(t.payload.prompt||t.payload.query);toast('Prompt copié')}if(el.dataset.upload){uploadSlot={job:selected,slot:el.dataset.upload};$('#fileInput').accept=el.dataset.type==='video'?'video/mp4,video/webm':'image/png,image/jpeg,image/webp';$('#fileInput').value='';$('#fileInput').click()}if(action==='saveScript'){await api('/api/job/'+selected,{action:'edit_script',script:reviewChanges()});reviewDirty=false;await refresh(true);toast('Corrections enregistrées');return}if(action==='approveScript'){await api('/api/job/'+selected,{action:'edit_script',script:reviewChanges()});await api('/api/job/'+selected,{action:'approve_script'});reviewDirty=false;await refresh(true);toast('Histoire validée : images lancées');return}if(el.dataset.redo){const slot=el.dataset.redo,isClip=slot.startsWith('clip:'),withClip=el.dataset.hasClip==='1';const what=slot==='cover'?'la couverture':slot.startsWith('image:')?'l’image de la scène '+(Number(slot.split(':')[1])+1):isClip?'le clip de la scène '+(Number(slot.split(':')[1])+1):'les personnages';if(withClip&&!window.confirm('Le clip de cette scène a été animé depuis cette image. Refaire l’image ET le clip ? Le clip consommera des crédits Flow.'))return;if(isClip&&!window.confirm('Refaire '+what+' consommera des crédits Flow. Continuer ?'))return;const note=window.prompt('Refaire '+what+'. Correction à appliquer (facultatif) :','');if(note===null)return;await api('/api/job/'+selected,{action:'redo',slot,note,include_clip:withClip});await refresh(true);toast('Nouvelle tentative programmée ; le fichier précédent est conservé.');return}if(el.dataset.dryRun){const enabled=el.dataset.dryRun==='1';if(!enabled&&!window.confirm('Les prochains clips seront envoyés à Flow et consommeront des crédits. Continuer ?'))return;await api('/api/job/'+selected,{action:'set_dry_run',enabled});if(!enabled)await api('/api/job/'+selected,{action:'resume',flow_profile:$('#jobProfile')?.value});await refresh(true);toast(enabled?'Essai à blanc activé':'Production réelle lancée');return}if(el.dataset.action==='accountSwitched'){await api('/api/job/'+selected,{action:'account_switched'});await refresh(true);toast('Changement de compte confirmé');return}if(el.dataset.series){const note=window.prompt('Suite de l’épisode : une idée pour la partie suivante ? (facultatif)','');if(note===null)return;const r=await api('/api/job/'+selected,{action:'continue_series',note});selected=r.created;await refresh(true);toast('Partie suivante créée : mêmes personnages, scénario en cours');return}if(el.dataset.deleteJob){if(!window.confirm('Supprimer cette production du studio ? Son dossier est déplacé dans data/corbeille (récupérable).'))return;const r=await api('/api/job/'+selected,{action:'delete'});selected=null;await refresh(true);toast('Production déplacée dans la corbeille : '+r.trashed);return}if(el.dataset.support==='report'){const r=await fetch('/api/report');const text=await r.text();const box=$('#reportBox');box.textContent=text;box.hidden=false;try{await navigator.clipboard.writeText(text);toast('Rapport copié')}catch{toast('Rapport affiché ci-dessous : sélectionnez-le pour le copier')}return}if(el.dataset.support==='purge'){const r=await api('/api/maintenance/purge',{});await refresh(true);toast('Nettoyage : '+r.purge.tasks_removed+' tâche(s), '+r.purge.events_removed+' événement(s) ; copie gardée');return}if(el.dataset.night){const action=el.dataset.night;await api('/api/night',{action,job:['add','remove'].includes(action)?selected:undefined});await refresh(true);toast({add:'Ajoutée à la file de nuit',remove:'Retirée de la file de nuit',start:'File de nuit démarrée',stop:'File de nuit arrêtée'}[action]);return}if(el.dataset.accountTab){accountsTab=el.dataset.accountTab;render();return}if(el.dataset.forgetQuota){await api('/api/quota/forget',{service:el.dataset.forgetQuota});await refresh(true);toast('Limite oubliée');return}if(el.dataset.forgetWall){await api('/api/engine-account',{id:el.dataset.forgetWall,forget_wall:true});await refresh(true);toast('Limite oubliée');return}if(el.dataset.deleteEngineAccount){if(!window.confirm('Retirer ce compte du studio ?'))return;await api('/api/engine-account',{id:el.dataset.deleteEngineAccount,delete:true});await refresh(true);return}if(el.dataset.confirmNoClip){const slot=el.dataset.confirmNoClip,n=Number(slot.split(':')[1])+1;if(!window.confirm('Confirmez-vous qu’aucun clip de la scène '+n+' n’existe dans Flow ? Une nouvelle génération consommera des crédits.'))return;await api('/api/job/'+selected,{action:'confirm_no_clip',slot});await refresh(true);toast('Confirmation enregistrée. Cliquez sur Reprendre pour relancer la scène.');return}if(el.dataset.checkCredits){await api('/api/profile/check',{id:el.dataset.checkCredits});toast('Lecture du solde réel demandée à la passerelle Flow');await refresh(true);return}if(el.dataset.deleteProfile){const id=el.dataset.deleteProfile,p=state.profiles.find(p=>p.id===id);if(!p)return;if(!window.confirm('Supprimer le profil « '+p.label+' » de l’application ? Les vidéos et le compte Google seront conservés.'))return;await api('/api/profile/delete',{id});await refresh(true);toast('Profil supprimé. Les productions et les vidéos sont conservées.');return}if(el.dataset.balance){const id=el.dataset.balance,p=state.profiles.find(p=>p.id===id);await api('/api/profile',{id,label:p.label,balance:Number($('#balance-'+id).value),...(p.flow_url?{auto_enabled:$('#auto-'+id).checked,chrome_profile:$('#chrome-'+id).value}:{})});await refresh(true)}}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.closest?.('#scriptReview'))reviewDirty=true;if(e.target.name==='language'){const queries={'Deutsch (de-DE)':'KI Früchte Geschichten deutsch','Français (fr-FR)':'histoires fruits IA français','English (en-US)':'AI fruit drama stories English'};document.querySelector('[name=query]').value=queries[e.target.value]||queries['Deutsch (de-DE)'];}});
document.addEventListener('change',async e=>{if(e.target.id==='flowAuto'){try{await api('/api/flow-auto',{enabled:e.target.checked});await refresh(true);toast(e.target.checked?'Passage automatique activé':'Passage automatique désactivé')}catch(err){toast(err.message)}}if(e.target.id==='jobProvider'){try{await api('/api/job/'+selected,{action:'provider',provider:e.target.value});toast('IA modifiée pour les prochaines tâches de scénario');await refresh(true)}catch(err){toast(err.message)}}});
document.addEventListener('submit',async e=>{if(e.target.id==='createForm'){e.preventDefault();const f=new FormData(e.target);try{await api('/api/job',{brief:String(f.get('brief')||'').trim()||'Choisis le sujet après la recherche des références. Invente une histoire originale adaptée à la référence retenue, sans en copier les dialogues ou les plans.',flow_profile:f.get('flow_profile'),source_url:String(f.get('source_url')||'').trim(),config:{provider:f.get('provider'),scene_count:Number(f.get('scene_count')),query:f.get('query'),language:f.get('language'),flow_cost:Number(f.get('flow_cost')),flow_model:f.get('flow_model'),video_engine:f.get('video_engine')||'flow',review_script:f.get('review_script')==='on',dry_run:f.get('dry_run')==='on',karaoke:f.get('karaoke')==='on'}});$('#createDialog').close();await refresh();selected=state.jobs[0].id;page='studio';render();toast('Production créée : recherche en attente du connecteur')}catch(err){toast(err.message)}}if(e.target.id==='engineAccountForm'){e.preventDefault();const f=new FormData(e.target);try{if(f.get('engine')==='flow')await api('/api/profile',{label:f.get('email'),balance:Number(f.get('balance')||0)});else await api('/api/engine-account',{engine:f.get('engine'),email:f.get('email'),label:f.get('email')});await refresh(true);toast('Compte ajouté')}catch(err){toast(err.message)}}if(e.target.id==='profileForm'){e.preventDefault();const f=new FormData(e.target);try{await api('/api/profile',{label:f.get('label'),balance:Number(f.get('balance'))});await refresh(true)}catch(err){toast(err.message)}}});
$('#fileInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file||!uploadSlot)return;try{toast('Import en cours…');const ext=file.name.split('.').pop().toLowerCase();const r=await fetch(`/api/upload?job=${uploadSlot.job}&slot=${encodeURIComponent(uploadSlot.slot)}&ext=${ext}`,{method:'POST',body:file});const b=await r.json();if(!r.ok)throw Error(b.error);await refresh(true);toast('Média importé, progression enregistrée')}catch(err){toast(err.message)}});
window.addEventListener('hashchange',()=>{const job=new URLSearchParams(location.hash.slice(1)).get('job');if(!job||job===selected)return;if(reviewDirty&&!window.confirm('Des corrections de l’histoire ne sont pas enregistrées. Les abandonner ?'))return;reviewDirty=false;selected=job;page='studio';render();});
$('#refresh').onclick=()=>refresh(true);refresh();setInterval(()=>refresh(),4000);

document.addEventListener('change',e=>{if(e.target.matches('#createForm [name=video_engine]')){const flow=e.target.value==='flow';document.querySelectorAll('#createForm .flow-only').forEach(x=>x.hidden=!flow)}if(e.target.matches('#createForm [name=flow_model]'))$('#createForm [name=flow_cost]').value=({gemini_omni_flash:12,veo_3_1_lite:10,veo_3_1_fast:20,veo_3_1_quality:100}[e.target.value]||12);});

// Click any production image to see it full screen.
document.addEventListener('click',e=>{const img=e.target.closest?.('.asset img,.cover-preview');if(!img)return;let box=$('#lightbox');if(!box){box=document.createElement('dialog');box.id='lightbox';box.addEventListener('click',()=>box.close());document.body.append(box);}box.innerHTML=`<img src="${img.src}" alt="${esc(img.alt)}">`;box.showModal();});

// Dark theme by default (Atelier look), light theme on demand; remembered on this computer.
const applyTheme=()=>document.body.classList.toggle('dark',localStorage.getItem('frucht-theme')!=='light');applyTheme();$('#theme').onclick=()=>{localStorage.setItem('frucht-theme',document.body.classList.contains('dark')?'light':'dark');applyTheme();};

paintIcons();
document.addEventListener('change',e=>{if(e.target.matches('#engineAccountForm [name=engine]'))document.querySelector('#engineAccountForm .flow-balance').hidden=e.target.value!=='flow';});

// Filon interactions: drag a card onto the creation zone, paste a TikTok link anywhere, copy links.
const tiktokLink=t=>{const m=String(t||'').match(/https:\/\/(?:www\.|vm\.|m\.)?tiktok\.com\/[^\s"'<>]+/);return m?m[0]:null;};
const openCreate=url=>{$('#createProfile').innerHTML=profileOptions(state.profiles[0]?.id);$('#createForm [name=source_url]').value=url||'';$('#createDialog').showModal();};
document.addEventListener('dragstart',e=>{const card=e.target.closest?.('.filon-card');if(!card)return;e.dataTransfer.setData('text/uri-list',card.dataset.url);e.dataTransfer.setData('text/plain',card.dataset.url);card.classList.add('dragging');document.querySelector('.dropzone')?.classList.add('ready');});
document.addEventListener('dragend',e=>{e.target.closest?.('.filon-card')?.classList.remove('dragging');document.querySelector('.dropzone')?.classList.remove('ready','over');});
document.addEventListener('dragover',e=>{const z=e.target.closest?.('[data-drop]');if(z){e.preventDefault();z.classList.add('over');}});
document.addEventListener('dragleave',e=>{e.target.closest?.('[data-drop]')?.classList.remove('over');});
document.addEventListener('drop',e=>{const z=e.target.closest?.('[data-drop]');if(!z)return;e.preventDefault();z.classList.remove('over','ready');const url=tiktokLink(e.dataTransfer.getData('text/uri-list')||e.dataTransfer.getData('text/plain'));url?openCreate(url):toast('Dépose une vidéo TikTok du Filon ou un lien TikTok.');});
document.addEventListener('paste',e=>{if(e.target.closest?.('input,textarea,[contenteditable="true"]'))return;const url=tiktokLink(e.clipboardData?.getData('text'));if(url){e.preventDefault();openCreate(url);toast('Lien TikTok collé : création prête');}});
document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-copy],[data-filon-refresh]');if(!b)return;try{if(b.dataset.copy){await navigator.clipboard.writeText(b.dataset.copy).catch(()=>{});toast('Lien copié');}else{await api('/api/filon',{refresh:true});await refresh(true);toast('Actualisation du Filon lancée');}}catch(err){toast(err.message)}});
document.addEventListener('change',async e=>{if(e.target.id==='filonAuto'){try{await api('/api/filon',{auto:e.target.checked});await refresh(true);toast(e.target.checked?'Filon actualisé toutes les 2 h':'Actualisation automatique arrêtée')}catch(err){toast(err.message)}}});
